63	func spaFallbackMiddleware(frontendFS fs.FS) echo.MiddlewareFunc {
64		return func(next echo.HandlerFunc) echo.HandlerFunc {
65			return func(c *echo.Context) error {
66				err := next(c)
67				if err == nil {
68					return nil
69				}
70	
71				requestPath := c.Request().URL.Path
72				if shouldSkipFrontendStatic(requestPath) || !shouldServeFrontendHTML(requestPath) || echo.StatusCode(err) != http.StatusNotFound {
73					return err
74				}
75	
76				setFrontendCacheHeaders(c, requestPath)
77				return c.FileFS("index.html", frontendFS)
78			}
79		}
80	}
